    ('tse-2026-90002543556', 'c42bd3e6-1036-4da1-a78d-5b6e468bd6e8'::uuid, '5278979-19.2023.8.09.0051', 'curadoria-djen-20260928: Comunicações processuais oficiais do DJEN/CNJ - processo 5278979-19.2023.8.09.0051')
  ) SELECT count(*) INTO n FROM expected e WHERE
    (SELECT count(*) FROM public.candidatos c JOIN public.processos p ON p.candidato_id = c.id
      WHERE c.id = e.candidato_id AND c.slug = e.slug AND p.fonte = e.fonte
        AND regexp_replace(p.numero_processo, '[^0-9]', '', 'g') = regexp_replace(e.numero_cnj, '[^0-9]', '', 'g')) <> 1;
  IF n <> 0 THEN RAISE EXCEPTION 'readback processos: % CNJs ausentes ou duplicados (esperados 83)', n; END IF;
